raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R11-01",
   "status": "OK",
   "label": "저금통 특별금리 적용",
   "source": {
    "quote": "계좌의 출금가능 잔액 범위 내에서 저금통으로 설정된 금액에 대해 특별금리 제공"
   },
   "condition": {
    "and": [
     {
      "exists": [
       {
        "var": "contract.low_balance_account"
       }
      ]
     },
     {
      ">=": [
       {
        "var": "account.balance"
       },
       {
        "var": "account.reserved_amount"
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.5,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-02",
   "status": "OK",
   "label": "저금통 해제 시 특별금리 해지",
   "source": {
    "quote": "다른 예금 상품으로 전환하는 경우 저금통은 자동 해제됨"
   },
   "condition": {
    "==": [
     {
      "var": "contract.channel"
     },
     "PRODUCT_SWITCH"
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-03",
   "status": "OK",
   "label": "거래 정정 시 실제 잔액 기준 특별금리 적용",
   "source": {
    "quote": "거래 정정 등 부득이한 사유로 저금통 설정금액보다 실제 잔액이 더 적은 경우에는 실제 잔액에 대하여 결산일 현재 지점에 게시한 특별금리 적용"
   },
   "condition": {
    "==": [
     {
      "var": "contract.channel"
     },
     "TRANSACTION_CORRECTION"
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": 0.5,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  }
 ]
}

